    "Confirm with pharmacy": ["ಔಷಧಾಲಯದಲ್ಲಿ ದೃಢೀಕರಿಸಿ", "फ़ार्मेसी से पुष्टि करें"],
    "Stock reservation": ["ದಾಸ್ತಾನು ಕಾಯ್ದಿರಿಸುವಿಕೆ", "भंडार आरक्षण"],
    "Not available in this prototype": ["ಈ ಮಾದರಿಯಲ್ಲಿ ಲಭ್ಯವಿಲ್ಲ", "इस प्रोटोटाइप में उपलब्ध नहीं"],
    "Search medicine": ["ಔಷಧಿ ಹುಡುಕಿ", "दवा खोजें"],
    "Search medicine name...": ["ಔಷಧಿಯ ಹೆಸರನ್ನು ಹುಡುಕಿ...", "दवा का नाम खोजें..."],
    "No medicine listings match your search.": ["ನಿಮ್ಮ ಹುಡುಕಾಟಕ್ಕೆ ಯಾವುದೇ ಔಷಧಿ ಪಟ್ಟಿ ಹೊಂದಿಕೆಯಾಗಿಲ್ಲ.", "आपकी खोज से दवा की कोई सूची मेल नहीं खाती।"],
    "Currently unavailable. Other nearby listings may have stock, but they are not medical substitutes. Confirm any change with your doctor or pharmacist.": ["ಪ್ರಸ್ತುತ ಲಭ್ಯವಿಲ್ಲ. ಹತ್ತಿರದ ಇತರ ಪಟ್ಟಿಗಳಲ್ಲಿ ದಾಸ್ತಾನು ಇರಬಹುದು, ಆದರೆ ಅವು ವೈದ್ಯಕೀಯ ಪರ್ಯಾಯಗಳಲ್ಲ. ಬದಲಾವಣೆಯನ್ನು ವೈದ್ಯರು ಅಥವಾ ಔಷಧಿಕಾರರೊಂದಿಗೆ ದೃಢೀಕರಿಸಿ.", "अभी उपलब्ध नहीं। पास की अन्य सूची में दवा हो सकती है, लेकिन वह चिकित्सा विकल्प नहीं है। बदलाव डॉक्टर या फ़ार्मासिस्ट से पूछकर करें।"],
    "Check other nearby listings": ["ಹತ್ತಿರದ ಇತರ ಪಟ್ಟಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ", "पास की दूसरी सूचियाँ जाँचें"],
    "View pharmacy": ["ಔಷಧಾಲಯ ವೀಕ್ಷಿಸಿ", "फ़ार्मेसी देखें"],
    "Get directions": ["ದಾರಿ ಪಡೆಯಿರಿ", "दिशा-निर्देश पाएँ"],
    "Availability and quantity are sample data. Confirm with the provider. Do not substitute a prescribed medicine without consulting your doctor or pharmacist.": ["ಲಭ್ಯತೆ ಮತ್ತು ಪ್ರಮಾಣ ಮಾದರಿ ಮಾಹಿತಿ ಮಾತ್ರ. ಪೂರೈಕೆದಾರರಿಂದ ದೃಢೀಕರಿಸಿ. ವೈದ್ಯರು ಅಥವಾ ಔಷಧಿಕಾರರನ್ನು ಸಂಪರ್ಕಿಸದೆ ಸೂಚಿಸಿದ ಔಷಧಿಯನ್ನು ಬದಲಿಸಬೇಡಿ.", "उपलब्धता और मात्रा नमूना डेटा है। प्रदाता से पुष्टि करें। डॉक्टर या फ़ार्मासिस्ट से पूछे बिना निर्धारित दवा न बदलें।"],
    "Sample inventory only. Call ahead to confirm stock; this screen cannot reserve or dispense medicines.": ["ಮಾದರಿ ದಾಸ್ತಾನು ಮಾತ್ರ. ಸ್ಟಾಕ್ ದೃಢೀಕರಿಸಲು ಮುಂಚಿತವಾಗಿ ಕರೆ ಮಾಡಿ; ಈ ಪರದೆಯಿಂದ ಔಷಧಿ ಕಾಯ್ದಿರಿಸಲು ಅಥವಾ ವಿತರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.", "केवल नमूना भंडार। स्टॉक की पुष्टि के लिए पहले कॉल करें; इस स्क्रीन से दवा आरक्षित या वितरित नहीं की जा सकती।"],
    "Participating provider · sample listing": ["ಭಾಗವಹಿಸುವ ಪೂರೈಕೆದಾರ · ಮಾದರಿ ಪಟ್ಟಿ", "भाग लेने वाला प्रदाता · नमूना सूची"],
    "Search hospitals, doctors, beds, medicines, blood availability, ambulances and schemes": ["ಆಸ್ಪತ್ರೆಗಳು, ವೈದ್ಯರು, ಹಾಸಿಗೆಗಳು, ಔಷಧಿಗಳು, ರಕ್ತ ಲಭ್ಯತೆ, ಆಂಬ್ಯುಲೆನ್ಸ್‌ಗಳು ಮತ್ತು ಯೋಜನೆಗಳನ್ನು ಹುಡುಕಿ", "अस्पताल, डॉक्टर, बिस्तर, दवाइयाँ, रक्त उपलब्धता, एम्बुलेंस और योजनाएँ खोजें"],
    "Clinician names and appointment availability are illustrative. This prototype does not book a real appointment.": ["ವೈದ್ಯರ ಹೆಸರುಗಳು ಮತ್ತು ನೇಮಕಾತಿ ಲಭ್ಯತೆ ಮಾದರಿ ಮಾಹಿತಿ ಮಾತ್ರ. ಈ ಮಾದರಿ ನೈಜ ನೇಮಕಾತಿ ಕಾಯ್ದಿರಿಸುವುದಿಲ್ಲ.", "डॉक्टरों के नाम और अपॉइंटमेंट उपलब्धता केवल उदाहरण हैं। यह प्रोटोटाइप वास्तविक अपॉइंटमेंट बुक नहीं करता।"],
    "Ambulance Availability": ["ಆಂಬ್ಯುಲೆನ್ಸ್ ಲಭ್ಯತೆ", "एम्बुलेंस उपलब्धता"],
    "Preview nearby response options. This demo does not contact emergency services.": ["ಹತ್ತಿರದ ಪ್ರತಿಕ್ರಿಯೆ ಆಯ್ಕೆಗಳನ್ನು ಪೂರ್ವವೀಕ್ಷಿಸಿ. ಈ ಡೆಮೋ ತುರ್ತು ಸೇವೆಗಳನ್ನು ಸಂಪರ್ಕಿಸುವುದಿಲ್ಲ.", "पास के प्रतिक्रिया विकल्प देखें। यह डेमो आपातकालीन सेवाओं से संपर्क नहीं करता।"],
    "Request ambulance": ["ಆಂಬ್ಯುಲೆನ್ಸ್ ವಿನಂತಿಸಿ", "एम्बुलेंस अनुरोध करें"],
    "The availability, distances and ETAs below are illustrative only; requesting here will not dispatch an ambulance.": ["ಕೆಳಗಿನ ಲಭ್ಯತೆ, ದೂರ ಮತ್ತು ತಲುಪುವ ಸಮಯ ಮಾದರಿ ಮಾಹಿತಿ ಮಾತ್ರ; ಇಲ್ಲಿ ವಿನಂತಿಸಿದರೆ ಆಂಬ್ಯುಲೆನ್ಸ್ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.", "नीचे दी गई उपलब्धता, दूरी और पहुँचने का समय केवल उदाहरण हैं; यहाँ अनुरोध करने से एम्बुलेंस नहीं भेजी जाएगी।"],
    "Blood Availability": ["ರಕ್ತ ಲಭ್ಯತೆ", "रक्त उपलब्धता"],
    "Government Schemes": ["ಸರ್ಕಾರಿ ಯೋಜನೆಗಳು", "सरकारी योजनाएँ"],
