    "Back to bed availability": ["ಹಾಸಿಗೆ ಲಭ್ಯತೆಗೆ ಹಿಂತಿರುಗಿ", "बिस्तर उपलब्धता पर वापस जाएँ"],
    "Back to medicine availability": ["ಔಷಧಿ ಲಭ್ಯತೆಗೆ ಹಿಂತಿರುಗಿ", "दवा उपलब्धता पर वापस जाएँ"],
    "Search hospitals, doctors, medicines and more...": ["ಆಸ್ಪತ್ರೆಗಳು, ವೈದ್ಯರು, ಔಷಧಿಗಳು ಮತ್ತು ಹೆಚ್ಚಿನದನ್ನು ಹುಡುಕಿ...", "अस्पताल, डॉक्टर, दवाइयाँ और अन्य सेवाएँ खोजें..."],
    "Search connected care services": ["ಸಂಪರ್ಕಿತ ಆರೈಕೆ ಸೇವೆಗಳನ್ನು ಹುಡುಕಿ", "जुड़ी हुई देखभाल सेवाएँ खोजें"],
    "No results found": ["ಯಾವುದೇ ಫಲಿತಾಂಶಗಳು ಕಂಡುಬಂದಿಲ್ಲ", "कोई परिणाम नहीं मिला"],
